// @ts-check
import js from "@eslint/js"
import reactHooks from "eslint-plugin-react-hooks"
import globals from "globals"
import tseslint from "typescript-eslint"

export default tseslint.config(
  {
    ignores: [
      "**/dist/**",
      "**/node_modules/**",
      "**/.output/**",
      "**/routeTree.gen.ts",
      // Generated by the shadcn CLI; customised by hand but not linted.
      "adapters/inbound/web/src/components/ui/**",
      "adapters/inbound/web/src/hooks/use-mobile.ts",
      "scripts/*.d.mts",
      ".data/**"
    ]
  },
  js.configs.recommended,
  ...tseslint.configs.strictTypeChecked,
  {
    languageOptions: {
      globals: { ...globals.node },
      parserOptions: { projectService: true, tsconfigRootDir: import.meta.dirname }
    },
    rules: {
      "@typescript-eslint/no-unused-vars": ["error", { argsIgnorePattern: "^_", varsIgnorePattern: "^_" }],
      "@typescript-eslint/restrict-template-expressions": ["error", { allowNumber: true }],
      // Effect generators use `yield*` on values whose types eslint cannot always see through.
      "require-yield": "off",
      "@typescript-eslint/no-confusing-void-expression": "off",
      "@typescript-eslint/no-non-null-assertion": "off",
      // Never log with console in application code: use Effect's logger.
      "no-console": ["error", { allow: ["error"] }]
    }
  },
  {
    files: ["adapters/inbound/web/**/*.{ts,tsx}"],
    languageOptions: { globals: { ...globals.browser } },
    plugins: { "react-hooks": reactHooks },
    rules: {
      ...reactHooks.configs.recommended.rules,
      // TanStack Router redirects are thrown objects by design.
      "@typescript-eslint/only-throw-error": "off"
    }
  },
  // Hexagonal architecture. core (domain, application, ports) depends on Effect only. Outbound adapters implement the
  // outbound ports (`@code-to-rag/core/outbound`) and never import each other. Inbound adapters call the inbound
  // ports (`@code-to-rag/core`); only their composition roots import the outbound adapters.
  {
    files: ["packages/core/src/**/*.ts"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              regex: "^(?!\\.{1,2}/|effect(/|$))",
              message:
                "core depends on Effect only: define an outbound port in packages/core/src/ports/outbound and implement it in an adapter."
            }
          ]
        }
      ]
    }
  },
  ...["postgres", "openai", "ollama", "filesystem"].map((adapter) => ({
    files: [`adapters/outbound/${adapter}/{src,test}/**/*.ts`],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              regex: `^@code-to-rag/(?!core(/|$)|${adapter}(/|$))`,
              message: "Outbound adapters depend on core only, never on each other or on the inbound adapters."
            },
            {
              regex: "^@code-to-rag/core$",
              message: "Outbound adapters implement the outbound ports: import @code-to-rag/core/outbound."
            },
            { regex: "^(\\.\\./)+.*packages/core/", message: "Import core through its package entry points." }
          ]
        }
      ]
    }
  })),
  {
    files: ["adapters/inbound/*/src/**/*.{ts,tsx}"],
    ignores: [
      // Composition roots: they wire the outbound adapters to the ports.
      "adapters/inbound/web/src/server/runtime.server.ts",
      "adapters/inbound/web/src/server/auth.server.ts",
      "adapters/inbound/worker/src/main.ts",
      "adapters/inbound/worker/src/migrate.ts"
    ],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              regex: "^@code-to-rag/(postgres|openai|ollama|filesystem)(/|$)",
              message: "Inbound adapters call the inbound ports; only the composition roots import outbound adapters."
            },
            {
              regex: "^@code-to-rag/core/(outbound|testing)$",
              message: "Inbound adapters use the inbound ports of @code-to-rag/core (Projects, Jobs, Knowledge…)."
            }
          ]
        }
      ]
    }
  },
  {
    files: ["**/*.js", "**/*.mjs", "vitest.config.ts"],
    ...tseslint.configs.disableTypeChecked
  },
  {
    // Command-line scripts report through the console.
    files: ["scripts/**"],
    rules: { "no-console": "off" }
  }
)
